def find_pivot(stock):
    total = sum(stock)   # total sum of entire array
    left_sum = 0
    for i in range(len(stock)):
        # right_sum = total - left_sum - stock[i]
        if left_sum == total - left_sum - stock[i]:
            return i
        left_sum += stock[i]  # include stock[i] in left sum for next iteration
    return -1

