def min_zone_length(crowd, threshold):
    n = len(crowd)
    min_len = float('inf')
    for i in range(n):
        curr_sum = 0
        for j in range(i, n):
            curr_sum += crowd[j]
            if curr_sum >= threshold:
                min_len = min(min_len, j - i + 1)
                break  # no need to extend further from i
    return 0 if min_len == float('inf') else min_len

def count_divisible_subarrays(signal, k):
    n = len(signal)
    count = 0
    for i in range(n):
        curr_sum = 0
        for j in range(i, n):
            curr_sum += signal[j]
            if curr_sum % k == 0:
                count += 1
    return count
